"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFeatureContent } from "./components/feature-sections/content";
import View10 from "./components/feature-sections/variants/11-bento";
const variants = {"bento":View10};
export type { ArtemisFeatureContent, ArtemisFeatureImage, ArtemisFeatureItem, ArtemisFeatureLink } from "./components/feature-sections/content";
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "bento"; /** The words on the feature section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFeatureContent>; }
export function ArtemisFeatureSections({ className, variant = "bento", content }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisFeatureLink {
  label: string;
  href: string;
}

/** A picture shown as content, and the words that stand in for it. */
export interface ArtemisFeatureImage {
  src: string;
  alt: string;
}

/** One feature: a row, card, step or tab, depending on the layout. */
export interface ArtemisFeatureItem {
  /** The feature's name. All layouts; signal-grid puts its first word on a line of its own. */
  title: string;
  /** A sentence or two about the feature. All layouts; product-hotspots, steps, tabs and stage-tabs show it for the chosen feature only. */
  description: string;
  /** A short name: the tab in tabs and stage-tabs (which show the title when you leave this out), and the words after the number in alternating-rows. */
  label?: string;
  /** Short points under the description. alternating-rows, product-hotspots and tabs. */
  bullets?: string[];
  /** A figure shown large. voice-ai (first card) and control-deck (third and fourth cards; on the third, a trailing % is set small and fills the bar). */
  stat?: string;
  /** The feature's icon. visual-benefits, signal-grid, voice-ai (first card), control-deck (fourth and fifth cards) and tabs, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
  /** A product picture. tabs, which shows its own picture for that slot when you leave this out. */
  image?: ArtemisFeatureImage;
}

/**
 * The words on an Artemis feature section. Every layout reads this shape, so you can switch layouts and keep them.
 * An empty `badge`, `headlineAccent` or `subhead` leaves that line out.
 */
export interface ArtemisFeatureContent {
  /** A short line above the headline. All layouts except visual-benefits, alternating-rows and stage-tabs. */
  badge?: string;
  /** The section heading. All layouts except stage-tabs. */
  headline?: string;
  /**
   * The second part of the heading. showcase, signal-grid, control-deck, voice-ai, list, bento and tabs put it on a
   * line of its own, steps sets it in the accent color, and the other layouts with a heading run it on after the
   * headline. It goes with `headline`: give a headline without it and the heading has no second part.
   */
  headlineAccent?: string;
  /** A sentence or two under the heading. All layouts except visual-benefits, tabs and stage-tabs. */
  subhead?: string;
  /**
   * The features. All layouts. Today's counts look best: three in visual-benefits, alternating-rows, showcase,
   * benefits-triptych and steps; four in product-hotspots, voice-ai, list, tabs and stage-tabs; five in control-deck
   * (which shows no more than five) and bento; six in signal-grid.
   */
  items: ArtemisFeatureItem[];
  /** The button under the features. visual-benefits. */
  cta?: ArtemisFeatureLink;
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, type Transition, useAnimate, useInView, useReducedMotion } from "motion/react";
import { type ReactNode, type RefObject, useEffect, useRef, useState } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { BracesIcon, BrainIcon, CheckIcon, FileTextIcon, GlobeIcon, MailIcon, SparklesIcon, TriangleAlertIcon, } from "./11-bento/icons";
import type { ArtemisFeatureContent, ArtemisFeatureItem } from "../content";
const DEFAULT = {
    badge: "Why agents",
    headline: "Everything your agent needs,",
    headlineAccent: "wired up out of the box.",
    subhead: "Tools, memory, streaming, and tracing — ship a production agent without stitching the plumbing together yourself.",
    items: [
        { title: "Watch the agent reason", description: "It plans, calls the right tools, and reports back — the full loop, streamed step by step." },
        { title: "Add a tool in one line", description: "Plug in any MCP server or function — the agent discovers and calls it automatically." },
        { title: "Remembers what matters", description: "Long-term memory and retrieval, baked in across runs." },
        { title: "Returns structured output", description: "Schema-valid, typed JSON every time — ready to use downstream." },
        { title: "Pauses for approval", description: "Asks before risky actions — approve or edit each step." },
    ],
} satisfies ArtemisFeatureContent;
/** What every card slot gets: its item, whether the demo has started, and (first card only) the ref that starts it. */
type SlotProps = {
    item: ArtemisFeatureItem;
    started: number;
    visualRef?: RefObject<HTMLDivElement | null>;
};
const WORD_STAGGER = 0.09;
const CARD_STAGGER = 0.08;
const INSTANT: Transition = { duration: 0 };
const POP_SPRING: Transition = { type: "spring", duration: 0.39, bounce: 0.35 };
const CIRC_OUT = [0, 0.55, 0.45, 1] as [
    number,
    number,
    number,
    number
];
function useStarted(ref: RefObject<HTMLDivElement | null>, amount: "some" | number = "some"): number {
    return useInView(ref, { once: true, amount }) ? 1 : 0;
}
function useCycle(ms: number, started: number): number {
    const [cycle, setCycle] = useState(0);
    useEffect(() => {
        if (!started)
            return;
        setCycle(0);
        const id = window.setInterval(() => setCycle((c) => c + 1), ms);
        return () => window.clearInterval(id);
    }, [ms, started]);
    return cycle;
}
function Heading({ lines }: { lines: string[][] }) {
    const ref = useRef<HTMLHeadingElement>(null);
    const inView = useInView(ref, { once: true });
    const reduce = useReducedMotion();
    let index = 0;
    return (<h2 ref={ref} className="art:block art:mt-5 art:text-balance art:text-foreground art:tracking-tight art:text-4xl art:font-medium">
      {lines.map((words, li) => (<span key={li} className="art:block">
          {words.map((word, wi) => {
                const delay = index++ * WORD_STAGGER;
                return (<motion.span key={wi} className="art:inline-block art:will-change-transform" initial={{ opacity: 0, filter: "blur(10px)", y: "40%" }} animate={inView || reduce ? { opacity: 1, filter: "blur(0px)", y: 0 } : undefined} transition={reduce ? INSTANT : {
                        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
                        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
                        y: { type: "spring", visualDuration: 0.48, bounce: 0, delay },
                    }}>
                {word}
                {wi < words.length - 1 ? <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span> : null}
              </motion.span>);
            })}
        </span>))}
    </h2>);
}
function Card({ index, className, children }: {
    index: number;
    className: string;
    children: ReactNode;
}) {
    const reduce = useReducedMotion();
    return (<motion.div className={className} initial={{ opacity: 0, filter: "blur(6px)", y: 22 }} whileInView={{ opacity: 1, filter: "blur(0px)", y: 0 }} viewport={{ once: true, amount: 0.25 }} transition={reduce ? INSTANT : { duration: 0.5, ease: ARTEMIS_EASE_OUT, delay: index * CARD_STAGGER }}>
      {children}
    </motion.div>);
}
function CardText({ title, body }: {
    title: string;
    body: string;
}) {
    return (<div className="art:shrink-0 art:mt-3">
      <h3 className="art:font-medium art:text-foreground art:text-xl">{title}</h3>
      <p className="art:mt-1 art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">{body}</p>
    </div>);
}
function Backdrop({ background }: {
    background: string;
}) {
    return (<div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:overflow-hidden art:bg-background">
      <div className="art:absolute art:inset-0 art:dark:opacity-35" style={{ background }}/>
      <div className="art:absolute art:inset-0 art:bg-background/10"/>
    </div>);
}
const BUBBLE_HIDDEN = { opacity: 0, filter: "blur(4px)", y: 8 };
const BUBBLE_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
function bubble(first: boolean, delay: number) {
    return {
        initial: first ? (false as const) : BUBBLE_HIDDEN,
        animate: BUBBLE_SHOWN,
        transition: { duration: 0.4, ease: ARTEMIS_EASE_OUT, delay },
    };
}
const TOOLS = [
    { name: "web_search", Icon: GlobeIcon },
    { name: "read_page", Icon: FileTextIcon },
    { name: "send_email", Icon: MailIcon },
];
function ChatRun({ first }: {
    first: boolean;
}) {
    return (<div className="art:flex art:w-full art:max-w-sm art:flex-col art:gap-2.5">
      <motion.div className="art:max-w-[88%] art:self-end art:rounded-2xl art:rounded-br-sm art:bg-white art:px-3.5 art:py-2 art:font-medium art:text-neutral-900 art:text-xs" {...bubble(first, 0.1)}>
        {"Find recent AI papers and email me a summary."}
      </motion.div>
      <motion.div className="art:border art:border-border art:bg-background/90 art:backdrop-blur-md art:self-start art:rounded-2xl art:rounded-bl-sm art:p-3" {...bubble(first, 0.55)}>
        <div className="art:mb-2 art:flex art:items-center art:gap-2 art:text-foreground art:text-xs">
          <span className="art:grid art:size-4 art:place-items-center art:rounded-full art:bg-background/90">
            <SparklesIcon />
          </span>
          <span className="art:font-medium">{"Working"}</span>
          <span className="art:flex art:gap-1">
            {[0, 1, 2].map((i) => (<motion.span key={i} className="art:size-1 art:rounded-full art:bg-white" animate={{ opacity: [0.25, 1, 0.25] }} transition={{ duration: 1, repeat: Number.POSITIVE_INFINITY, ease: "easeInOut", delay: i * 0.2 }}/>))}
          </span>
        </div>
        <div className="art:flex art:flex-col art:gap-1.5">
          {TOOLS.map(({ name, Icon }, i) => (<div key={name} className="art:flex art:items-center art:gap-2 art:text-foreground art:text-xs">
              <Icon />
              <span className="art:flex-1 art:font-mono art:text-xs">{name}</span>
              <motion.span className="art:grid art:size-4 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground" initial={first ? false : { scale: 0 }} animate={{ scale: 1 }} transition={{ ...POP_SPRING, delay: 1.3 + i * 0.5 }}>
                <CheckIcon className="art:size-2.5"/>
              </motion.span>
            </div>))}
        </div>
      </motion.div>
      <motion.div className="art:border art:border-border art:bg-background/90 art:backdrop-blur-md art:max-w-[92%] art:self-start art:rounded-2xl art:rounded-bl-sm art:px-3.5 art:py-2 art:text-foreground art:text-xs" {...bubble(first, 3.1)}>
        {"Sent 5 papers to your inbox \u2014 summary included."}
      </motion.div>
    </div>);
}
function ChatCard({ item, visualRef, started }: SlotProps) {
    const cycle = useCycle(6800, started);
    return (<Card index={0} className="art:relative art:flex art:flex-col art:overflow-hidden art:rounded-3xl art:border art:border-border/50 art:p-3 art:@min-[640px]/artemis:col-span-2 art:@min-[1024px]/artemis:col-span-4">
      <div ref={visualRef} className="art:relative art:h-[24rem] art:overflow-hidden art:rounded-2xl">
        <Backdrop background="radial-gradient(ellipse at 5% 0%, #b5d9f6 0%, transparent 65%), radial-gradient(ellipse at 95% 100%, #f4c9b8 0%, transparent 65%), #e7eee8"/>
        <div className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:p-6">
          <ChatRun key={cycle} first={cycle === 0}/>
        </div>
      </div>
      <CardText title={item.title} body={item.description}/>
    </Card>);
}
const CONNECTORS = ["web-search", "code-runner", "postgres", "gmail", "slack-mcp"];
function ToolsCard({ item, started }: SlotProps) {
    const [count, setCount] = useState(3);
    useEffect(() => {
        if (!started)
            return;
        setCount(1);
        const id = window.setInterval(() => setCount((c) => (c >= CONNECTORS.length ? 1 : c + 1)), 1100);
        return () => window.clearInterval(id);
    }, [started]);
    return (<Card index={1} className="art:relative art:flex art:flex-col art:overflow-hidden art:rounded-3xl art:border art:border-border/50 art:p-3 art:@min-[640px]/artemis:col-span-2 art:@min-[1024px]/artemis:col-span-2">
      <div className="art:relative art:h-[24rem] art:overflow-hidden art:rounded-2xl art:p-5">
        <Backdrop background="radial-gradient(ellipse at 5% 0%, #a8ccc8 0%, transparent 65%), radial-gradient(ellipse at 95% 100%, #c6d8ed 0%, transparent 65%), #e2e9e6"/>
        <div className="art:relative art:h-full art:overflow-hidden art:rounded-2xl art:border art:border-border art:p-4 art:font-mono art:text-xs art:backdrop-blur-md">
          <div className="art:mb-3 art:flex art:items-center art:gap-1.5">
            <span className="art:size-2.5 art:rounded-full art:bg-background/90"/>
            <span className="art:size-2.5 art:rounded-full art:bg-background/90"/>
            <span className="art:size-2.5 art:rounded-full art:bg-background/90"/>
          </div>
          <p className="art:text-foreground/45">{"$ agent tools add"}</p>
          <div className="art:mt-2 art:flex art:flex-col art:gap-1.5">
            <AnimatePresence initial={false}>
              {CONNECTORS.slice(0, count).map((name) => (<motion.div key={name} className="art:flex art:items-center art:gap-2 art:text-primary" initial={{ opacity: 0, x: -6 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0 }} transition={{ duration: 0.25, ease: ARTEMIS_EASE_OUT }}>
                  <span className="art:grid art:size-3.5 art:shrink-0 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
                    <CheckIcon className="art:size-2.5"/>
                  </span>
                  <span className="art:text-foreground/80">{"connected"}</span>
                  <span className="art:font-medium art:text-foreground">{name}</span>
                </motion.div>))}
            </AnimatePresence>
          </div>
        </div>
      </div>
      <CardText title={item.title} body={item.description}/>
    </Card>);
}
const MEMORIES = [
    "Prefers concise answers",
    "Stack: Postgres + Vercel",
    "Timezone GMT+5:30",
    "Default model: Quill",
    "Owns the deploy keys",
];
function MemoryCard({ item, started }: SlotProps) {
    return (<Card index={2} className="art:relative art:flex art:flex-col art:overflow-hidden art:rounded-3xl art:border art:border-border/50 art:p-3 art:@min-[1024px]/artemis:col-span-2">
      <div className="art:relative art:flex art:h-[13rem] art:items-center art:overflow-hidden art:rounded-2xl art:p-5">
        <Backdrop background="radial-gradient(ellipse at 5% 0%, #c6d5af 0%, transparent 65%), radial-gradient(ellipse at 95% 100%, #c7e3db 0%, transparent 65%), #edf0dc"/>
        <div className="art:relative art:h-[9rem] art:w-full art:overflow-hidden art:[mask-image:linear-gradient(to_bottom,transparent,black_18%,black_82%,transparent)]">
          <motion.div initial={{ y: "0%" }} animate={started ? { y: "-50%" } : undefined} transition={{ duration: 9, ease: "linear", repeat: Number.POSITIVE_INFINITY }}>
            {[...MEMORIES, ...MEMORIES].map((text, i) => (<div key={i} className="art:border art:border-border art:bg-background/90 art:backdrop-blur-md art:mb-1.5 art:flex art:items-center art:gap-2 art:rounded-xl art:px-3 art:py-2">
                <span className="art:grid art:size-5 art:shrink-0 art:place-items-center art:bg-background/90 art:text-foreground/80 art:rounded-full">
                  <BrainIcon />
                </span>
                <span className="art:truncate art:text-foreground art:text-xs">{text}</span>
              </div>))}
          </motion.div>
        </div>
      </div>
      <CardText title={item.title} body={item.description}/>
    </Card>);
}
const FIELDS: {
    key: string;
    value: string;
    comma: boolean;
}[] = [
    { key: "\"intent\"", value: "\"summarize\"", comma: true },
    { key: "\"sources\"", value: "5", comma: true },
    { key: "\"confidence\"", value: "0.94", comma: false },
];
function OutputCard({ item, started }: SlotProps) {
    const cycle = useCycle(3400, started);
    const first = cycle === 0;
    return (<Card index={3} className="art:relative art:flex art:flex-col art:overflow-hidden art:rounded-3xl art:border art:border-border/50 art:p-3 art:@min-[1024px]/artemis:col-span-2">
      <div className="art:relative art:flex art:h-[13rem] art:items-center art:justify-center art:overflow-hidden art:rounded-2xl art:p-5">
        <Backdrop background="radial-gradient(ellipse at 5% 0%, #edc49b 0%, transparent 65%), radial-gradient(ellipse at 95% 100%, #f2d6c9 0%, transparent 65%), #f4eadb"/>
        <div className="art:relative art:w-full art:max-w-[15rem] art:rounded-2xl art:border art:border-border art:bg-background art:p-3.5 art:backdrop-blur-md">
          <div className="art:flex art:items-center art:justify-between">
            <span className="art:flex art:items-center art:gap-1.5 art:font-mono art:text-foreground art:text-xs">
              <BracesIcon />
              {" output.json"}
            </span>
            <motion.span key={cycle} className="art:inline-flex art:items-center art:gap-1 art:rounded-md art:bg-primary art:px-1.5 art:py-0.5 art:text-xs art:text-primary-foreground" initial={first ? false : { opacity: 0, scale: 0.7 }} animate={{ opacity: 1, scale: 1 }} transition={{ ...POP_SPRING, delay: 1.5 }}>
              <CheckIcon className="art:size-2.5"/>
              {" schema"}
            </motion.span>
          </div>
          <div key={cycle} className="art:mt-2.5 art:font-mono art:text-xs art:leading-5">
            <p className="art:text-foreground/45">{"{"}</p>
            {FIELDS.map((f, i) => (<motion.p key={f.key} className="art:pl-3" initial={first ? false : { opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.28, ease: ARTEMIS_EASE_OUT, delay: 0.2 + i * 0.4 }}>
                <span className="art:text-sky-300">{f.key}</span>
                <span className="art:text-foreground/45">{": "}</span>
                <span className="art:text-primary">{f.value}</span>
                {f.comma ? <span className="art:text-foreground/45">{","}</span> : null}
              </motion.p>))}
            <p className="art:text-foreground/45">{"}"}</p>
          </div>
        </div>
      </div>
      <CardText title={item.title} body={item.description}/>
    </Card>);
}
function ApproveButton({ first, run }: {
    first: boolean;
    run: boolean;
}) {
    const [scope, animate] = useAnimate<HTMLButtonElement>();
    const [approved, setApproved] = useState(first);
    useEffect(() => {
        if (!run)
            return;
        const press = window.setTimeout(() => {
            if (scope.current) {
                animate(scope.current, { scale: [1, 0.93, 1] }, { duration: 0.5, times: [0, 0.5, 1], ease: [ARTEMIS_EASE_OUT, ARTEMIS_EASE_OUT] });
            }
        }, 1000);
        const approve = window.setTimeout(() => setApproved(true), 1300);
        return () => {
            window.clearTimeout(press);
            window.clearTimeout(approve);
        };
    }, [animate, scope, run]);
    return (<button ref={scope} type="button" className="art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:hover:bg-transparent art:hover:text-inherit art:flex art:flex-1 art:items-center art:justify-center art:gap-1.5 art:bg-primary art:py-2 art:font-medium art:text-xs art:text-primary-foreground art:rounded-full" tabIndex={0} style={{ transform: "none" }}>
      <motion.span className="art:inline-flex" initial={first ? false : { opacity: 0, scale: 0 }} animate={approved ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0 }} transition={POP_SPRING}>
        <CheckIcon className="art:size-3"/>
      </motion.span>
      {"Approve"}
    </button>);
}
function ApprovalCard({ item, started }: SlotProps) {
    const cycle = useCycle(3000, started);
    return (<Card index={4} className="art:relative art:flex art:flex-col art:overflow-hidden art:rounded-3xl art:border art:border-border/50 art:p-3 art:@min-[1024px]/artemis:col-span-2">
      <div className="art:relative art:flex art:h-[13rem] art:items-center art:justify-center art:overflow-hidden art:rounded-2xl art:p-5">
        <Backdrop background="radial-gradient(ellipse at 5% 0%, #a9d4dd 0%, transparent 65%), radial-gradient(ellipse at 95% 100%, #d3dbb6 0%, transparent 65%), #e7ede2"/>
        <div className="art:border art:border-border art:bg-background/90 art:backdrop-blur-md art:relative art:w-full art:max-w-[15rem] art:rounded-2xl art:p-3.5">
          <div className="art:flex art:items-center art:gap-1.5 art:text-xs art:text-foreground/80">
            <TriangleAlertIcon />
            <span className="art:font-medium">{"Approval needed"}</span>
          </div>
          <p className="art:mt-2 art:font-mono art:text-foreground art:text-xs">{"deploy \u2192 production?"}</p>
          <div className="art:mt-3 art:flex art:gap-2">
            {started ? <ApproveButton key={cycle} first={cycle === 0} run/> : <ApproveButton key="idle" first run={false}/>}
            <motion.button type="button" className="art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:h-auto art:p-0 art:hover:bg-transparent art:hover:text-inherit art:flex-1 art:border art:border-border art:bg-background/90 art:py-2 art:font-medium art:text-xs art:text-foreground art:rounded-full" tabIndex={0} whileHover={{ scale: 1.01 }} transition={{ duration: 0.15, ease: CIRC_OUT }}>
              {"Edit"}
            </motion.button>
          </div>
        </div>
      </div>
      <CardText title={item.title} body={item.description}/>
    </Card>);
}
const SLOTS = [ChatCard, ToolsCard, MemoryCard, OutputCard, ApprovalCard];
export default function FeatureSectionsBento({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const lines = [copy.headline, accent].flatMap((text) => (text ? [text.split(/\s+/).filter(Boolean)] : []));
    const chatVisual = useRef<HTMLDivElement>(null);
    const started = useStarted(chatVisual, 0.5);
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:max-w-2xl">
              {copy.badge ? <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">{copy.badge}</p> : null}
              <Heading lines={lines}/>
              {copy.subhead ? (<p className="art:mt-4 art:max-w-xl art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
                {copy.subhead}
              </p>) : null}
            </div>
